test("ajuste: un recuento menor agrega un egreso por la diferencia", () => {
  const antes = conIngreso();
  const despues = ajustarInventario(antes, { articulo: "A1", almacen: "LPZ", cantidadContada: 7, motivo: "recuento" });
  assert.equal(antes.length, 1);
  assert.equal(despues.length, 2);
  assert.equal(despues[1].tipo, "egreso");
  assert.equal(despues[1].cantidad, 3);
  assert.equal(despues[1].motivo, "recuento");
  assert.equal(stock(despues, "A1", "LPZ"), 7);
});

test("ajuste: un recuento mayor agrega un ingreso por la diferencia", () => {
  const despues = ajustarInventario(conIngreso(), { articulo: "A1", almacen: "LPZ", cantidadContada: 12, motivo: "recuento" });
  assert.equal(despues[1].tipo, "ingreso");
  assert.equal(despues[1].cantidad, 2);
  assert.equal(stock(despues, "A1", "LPZ"), 12);
});

test("ajuste: sin diferencia no agrega nada", () => {
  const antes = conIngreso();
  const despues = ajustarInventario(antes, { articulo: "A1", almacen: "LPZ", cantidadContada: 10, motivo: "recuento" });
  assert.equal(despues.length, 1);
  assert.deepEqual(despues, antes);
});

test("ajuste: recuento a cero de un artículo sin movimientos no agrega nada; datos inválidos se rechazan", () => {
  assert.equal(ajustarInventario([], { articulo: "A1", almacen: "LPZ", cantidadContada: 0, motivo: "recuento" }).length, 0);
  const base = { articulo: "A1", almacen: "LPZ", motivo: "recuento" };
  assert.throws(() => ajustarInventario(conIngreso(), { ...base, cantidadContada: -1 }), RangeError);
  assert.throws(() => ajustarInventario(conIngreso(), { ...base, cantidadContada: 1.5 }), RangeError);
  assert.throws(() => ajustarInventario(conIngreso(), { ...base, cantidadContada: 5, motivo: "" }));
});
